insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays,voice_profile) values('KLI-IELTS-L1','Listening Part 1 — Accommodation Enquiry','Transcript withheld during delivery','listening_script','Agent: Good morning, Riverside Student Housing. Student: I am starting a nine-month engineering course in September and need a room from the second of that month. Agent: We have a standard room at 145 pounds per week and a larger en-suite room at 185. Both include internet, but electricity is charged separately. Student: I will take the standard room. I do not have a car, so bicycle storage matters more than parking. Agent: The residence has a locked bicycle room beside Block C. A refundable deposit of 290 pounds is due within five days. Please email a passport copy and your student offer letter. Student: Can I arrive on a Sunday? Agent: Yes, but after six p.m. you must collect the key from security at the east gate. The nearest supermarket is on King Street, about an eight-minute walk away.',true,1,'{"language":"en-GB","rate":0.92,"pitch":1.0}'::jsonb) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=1,voice_profile=excluded.voice_profile;
