insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays,voice_profile) values('KLI-IELTS-L2','Listening Part 2 — Museum Volunteer Induction','Transcript withheld during delivery','listening_script','Coordinator: Welcome to the City Museum volunteer programme. The building opens to visitors at ten, but volunteers should arrive by nine thirty and sign in at the staff entrance. Your first two shifts will be in the discovery gallery, where families handle replica objects. Please demonstrate the objects, but do not answer questions about value; direct those to a curator. Blue lockers are available downstairs, and personal bags must not remain behind the desk. At eleven fifteen, one volunteer checks the interactive screens and records faults in the green folder. Lunch is from one until one forty-five in the staff kitchen. In an emergency, guide visitors to the north courtyard, not the main entrance. Next Saturday the museum will host a textile workshop, so the discovery gallery will close at three. Please complete the online safeguarding module before Friday evening.',true,1,'{"language":"en-GB","rate":0.92,"pitch":1.0}'::jsonb) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=1,voice_profile=excluded.voice_profile;
