insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays,voice_profile) values('KLI-IELTS-L3','Listening Part 3 — Research Project Meeting','Transcript withheld during delivery','listening_script','Supervisor: Let us refine your study of commuter cycling. Student: I planned to survey everyone entering the central station. Supervisor: That would overrepresent train users. Include the university gate and the hospital entrance as well. Student: I can collect data on Monday and Thursday mornings. Supervisor: Add one evening period because travel patterns change after work. Use the same six questions at every site, and pilot them with ten people before the main survey. Student: Should I ask for names? Supervisor: No. Record age range, journey purpose, distance, and reasons for choosing or avoiding a bicycle. Student: I also wanted to measure air quality. Supervisor: That would make the project too broad. Use the council''s published pollution data instead. Student: I will send the revised questionnaire on the twelfth. Supervisor: Good. Submit the ethics form two days earlier, and book a statistical consultation for the week after data collection.',true,1,'{"language":"en-GB","rate":0.92,"pitch":1.0}'::jsonb) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=1,voice_profile=excluded.voice_profile;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What is the project about?','["Train reliability", "Commuter cycling", "Hospital staffing", "Air pollution equipment"]'::jsonb,'Commuter cycling',1,21,'listening',0.55,s.id,'main_idea',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-IELTS-L3' where t.code='EN-IELTS-ACADEMIC-PRACTICE';
