insert into public.assessment_stimuli(code,title,content,stimulus_type,audio_script,content_hidden,max_plays,voice_profile) values('KLI-IELTS-L4','Listening Part 4 — Lecture on Urban Soil','Transcript withheld during delivery','listening_script','Lecturer: Urban soil is often treated as inert material, yet it supports vegetation, stores water, and contains complex communities of organisms. Its properties vary over very short distances because construction, demolition, gardening, and traffic move or compress the soil. Compaction reduces spaces that normally hold air and water, so roots may remain shallow even when nutrients are available. Researchers first map land-use history, then sample at several depths rather than collecting only surface soil. They measure texture, organic matter, acidity, and contaminants such as lead. High contaminant levels do not always require removing all soil. A clean layer can sometimes be added, or food crops can be moved into raised beds with imported soil. Trees present another challenge: species selected for rapid growth may fail during drought if their roots cannot penetrate compacted ground. Current projects therefore combine soil restoration with species selection and long-term monitoring. Community gardens can help researchers observe change, but volunteers need consistent sampling instructions if their data are to be compared across sites.',true,1,'{"language":"en-GB","rate":0.92,"pitch":1.0}'::jsonb) on conflict(code) do update set audio_script=excluded.audio_script,content_hidden=true,max_plays=1,voice_profile=excluded.voice_profile;
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What is the lecture mainly about?','["Urban soil functions and management", "The history of rural farming", "Traffic engineering", "Commercial tree sales"]'::jsonb,'Urban soil functions and management',1,31,'listening',0.55,s.id,'main_idea',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='listening' join public.assessment_stimuli st on st.code='KLI-IELTS-L4' where t.code='EN-IELTS-ACADEMIC-PRACTICE';
