insert into public.assessment_stimuli(code,title,content,stimulus_type,content_hidden) values('KLI-IELTS-R1','Reading Passage 1 — Restoring Urban Wetlands','Urban wetlands were once dismissed as unproductive land and were frequently drained for roads, housing, or industry. During the last several decades, however, researchers have documented services that these ecosystems provide. Wetland vegetation slows storm water, while soils and microorganisms retain or transform some pollutants before they enter rivers. Shallow water and varied plant structure also create habitat for insects, fish, and birds. These functions have encouraged cities to restore wetlands as part of flood management rather than relying entirely on concrete channels.
