insert into public.assessment_stimuli(code,title,content,stimulus_type,content_hidden) values('KLI-IELTS-R2','Reading Passage 2 — The Development of Public Time','For much of human history, communities did not need every clock to show precisely the same time. Daily activity followed daylight, local bells, and the observable position of the sun. A town could set noon when the sun reached its highest point, even though another town some distance east or west experienced solar noon at a different moment. Such variation caused little difficulty while most journeys were slow and communication depended on physical travel.
