insert into public.assessment_stimuli(code,title,content,stimulus_type,content_hidden) values('KLI-IELTS-R3','Reading Passage 3 — Citizen Science and Data Quality','Citizen science projects invite members of the public to contribute to research by observing wildlife, classifying images, measuring rainfall, or recording environmental conditions. Digital platforms allow thousands of volunteers to submit information across areas that professional researchers could not visit frequently. The resulting datasets can reveal migration patterns, seasonal changes, and rare events. Yet large numbers of observations do not automatically produce reliable evidence. Project design determines whether volunteer contributions can answer a scientific question.
insert into public.assessment_questions(test_id,prompt,options,correct_option,points,sort_order,competency,difficulty,section_id,item_type,randomize_options,stimulus_id) select t.id,'What is the central argument?','["Volunteer data is always unreliable", "Citizen science can be valuable when limitations are managed", "Professional surveys are no longer needed", "Digital platforms solve every sampling problem"]'::jsonb,'Citizen science can be valuable when limitations are managed',1,67,'reading',0.58,s.id,'main_idea',false,st.id from public.assessment_tests t join public.assessment_sections s on s.test_id=t.id and s.code='reading' join public.assessment_stimuli st on st.code='KLI-IELTS-R3' where t.code='EN-IELTS-ACADEMIC-PRACTICE';
